const Diseases = () => {
  const navigate = useNavigate();
  const { db, dbError } = useDb();
  const [openDrawer, setOpenDrawer] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [diseaseList, setDiseaseList] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [categories, setCategories] = useState([]);

  useEffect(() => {
    if (db) {
      try {
        const result = db.exec("SELECT Id, Name, ImagePath FROM Category");
        if (result.length > 0 && result[0].values.length > 0) {
          const fetchedCategories = result[0].values.map((row) => ({
            id: row[0],
            title: row[1],
            value: row[1] ? row[1].toLowerCase().replace(/\s+/g, "_") : "",
            imageUrl: row[2],
          }));
          setCategories(fetchedCategories);
        }
      } catch (error) {
        console.error("Error fetching categories:", error);
      }
    }
  }, [db]);

  const fetchDiseasesByCategory = async (categoryValue) => {
    setLoading(true);
    try {
      const existingData = JSON.parse(localStorage.getItem("diseases")) || [];
      const filteredData = existingData.filter(
        (d) => d.category_id === categoryValue || d.category === categoryValue,
      );
      setDiseaseList(filteredData);
    } catch (error) {
      setDiseaseList([]);
    } finally {
      setLoading(false);
    }
  };

  const handleDiseaseAdded = () => {
    if (selectedCategory) {
      fetchDiseasesByCategory(selectedCategory.value);
    }
  };

  const handleCategoryClick = (category) => {
    setSelectedCategory(category);
    fetchDiseasesByCategory(category.value);
  };

  const handleBackToCategories = () => {
    setSelectedCategory(null);
    setDiseaseList([]);
    setSearchTerm("");
  };

  const handleStartTreatment = async (disease, reference) => {
    try {
      if (!db) {
        alert("Database not loaded. Please refresh the page and try again.");
        return;
      }

      const items = disease.items || [];
      if (items.length === 0 && disease.surah_id) {
        items.push({
          type: "surah",
          itemId: disease.surah_id,
          count: disease.recitation_count || 7,
          ayat_from: disease.ayat_from || 1,
          ayat_to: disease.ayat_to || 7,
        });
      }

      const getItemName = (item) => {
        if (item.type === "surah") {
          const surah = SURAHS.find(
            (entry) => String(entry.surah_id) === String(item.itemId),
          );
          if (surah) return surah.EnglishName;
        }

        const table =
          item.type === "hadith"
            ? "hadiths"
            : item.type === "durood" || item.type === "darood"
              ? "duroods"
              : null;
        if (table) {
          try {
            const result = db.exec(`SELECT Name FROM ${table} WHERE Id = ?`, [
              item.itemId,
            ]);
            if (result.length > 0 && result[0].values.length > 0)
              return result[0].values[0][0];
          } catch (error) {
            console.warn(`Could not load ${item.type} name:`, error);
          }
        }

        return `${item.type} ${item.itemId}`;
      };

      const itemCounters = items.map((item) => {
        const name = getItemName(item);
        let verses = [];

        if (item.type === "surah") {
          try {
            const versesResult = db.exec(
              `SELECT VerseId, AyahText FROM Quran WHERE SuraId = ? AND VerseId >= ? AND VerseId <= ?`,
              [item.itemId, item.ayat_from || 1, item.ayat_to || 7],
            );
            if (versesResult.length > 0 && versesResult[0].values.length > 0) {
              verses = versesResult[0].values.map((row) => ({
                ayah_id: row[0],
                arabic: row[1],
              }));
            }
          } catch (error) {
            console.warn(`Could not load verses for ${name}:`, error);
          }
          if (verses.length === 0) {
            verses = [
              {
                ayah_id: `${name} ${item.ayat_from || 1}-${item.ayat_to || 7}`,
                arabic:
                  "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ",
              },
            ];
          }
        } else {
          verses = [
            {
              ayah_id: `${item.type}-${item.itemId}`,
              arabic: `Text for ${name}`,
            },
          ];
        }

        return {
          label:
            item.type === "surah" && item.ayat_from && item.ayat_to
              ? `${name} (Ayat ${item.ayat_from}-${item.ayat_to})`
              : name,
          type: item.type,
          target: Number(item.count) || 7,
          completed: 0,
          verses,
        };
      });

      const totalCount = itemCounters.reduce(
        (total, item) => total + item.target,
        0,
      );
      const allVerses = itemCounters.flatMap((item) => item.verses);

      const existingTreatments =
        JSON.parse(localStorage.getItem("treatments")) || [];
      const newTreatmentId = existingTreatments.length + 1;

      const newTreatment = {
        treatment_id: newTreatmentId,
        EnglishName: reference || "Combined Treatment",
        disease_name: disease.name,
        recitation_count: totalCount || 7,
        completed_count: 0,
        status: "in_progress",
        itemCounters,
        verses: allVerses,
      };

      const updatedTreatments = [...existingTreatments, newTreatment];
      localStorage.setItem("treatments", JSON.stringify(updatedTreatments));

      navigate("/app/treatments");
    } catch (error) {
      console.log("Error starting treatment:", error);
      alert("Failed to start treatment. Please try again.");
    }
  };

  return (
    <Box sx={{ p: 1 }}>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 4,
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          {selectedCategory && (
            <IconButton onClick={handleBackToCategories} color="primary">
              <ArrowBackIcon />
            </IconButton>
          )}
          <Typography variant="h3" sx={{ fontWeight: "bold" }}>
            {selectedCategory
              ? `${selectedCategory.title} Diseases`
              : "Diseases"}
          </Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setOpenDrawer(true)}
          sx={{
            borderRadius: 2,
            px: 3,
            textTransform: "none",
            fontSize: "1rem",
          }}
        >
          Add Disease
        </Button>
      </Box>

      <Box sx={{ mb: 4 }}>
        <TextField
          fullWidth
          variant="outlined"
          placeholder={
            selectedCategory
              ? `Search in ${selectedCategory.title}...`
              : "Search categories..."
          }
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon color="action" />
              </InputAdornment>
            ),
            sx: {
              borderRadius: 3,
              backgroundColor: "#ffffff",
              boxShadow: "0 2px 10px rgba(0,0,0,0.02)",
            },
          }}
        />
      </Box>

      {loading ? (
        <Box sx={{ display: "flex", justifyContent: "center", mt: 4 }}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          {!selectedCategory ? (
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: {
                  xs: "1fr",
                  md: "repeat(2, 1fr)",
                  lg: "repeat(3, 1fr)",
                },
                gap: 2,
              }}
            >
              {categories
                .filter((cat) =>
                  cat.title.toLowerCase().includes(searchTerm.toLowerCase()),
                )
                .map((category) => (
                  <Card
                    key={category.value}
                    onClick={() => handleCategoryClick(category)}
                    sx={{
                      height: "100%",

                      display: "flex",
                      flexDirection: "column",
                      cursor: "pointer",
                      borderRadius: 4,
                      overflow: "hidden",
                      boxShadow: "0 4px 15px rgba(0,0,0,0.05)",
                      transition: "all 0.3s ease",
                      "&:hover": {
                        transform: "translateY(-8px)",
                        boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
                      },
                    }}
                  >
                    <CardMedia
                      component="img"
                      height="180"
                      image={category.imageUrl}
                      alt={category.title}
                      sx={{ objectFit: "cover" }}
                    />
                    <CardContent
                      sx={{
                        textAlign: "center",
                        py: 2,
                        flexGrow: 1,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                      }}
                    >
                      <Typography variant="body1" sx={{ fontWeight: "bold" }}>
                        {category.title}
                      </Typography>
                    </CardContent>
                  </Card>
                ))}
            </Box>
          ) : (
            <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
              {diseaseList.length === 0 ? (
                <Box
                  sx={{
                    textAlign: "center",
                    mt: 8,
                    p: 4,
                    borderRadius: 4,
                    bgcolor: "rgba(0,0,0,0.02)",
                    border: "2px dashed rgba(0,0,0,0.1)",
                  }}
                >
                  <Typography
                    variant="h5"
                    sx={{ fontWeight: "bold", color: "text.secondary", mb: 2 }}
                  >
                    No diseases found in {selectedCategory.title}
                  </Typography>
                  <Typography
                    variant="body1"
                    sx={{ color: "text.secondary", mb: 4 }}
                  >
                    Be the first to add a treatment for this category!
                  </Typography>
                  <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    onClick={() => setOpenDrawer(true)}
                    sx={{ borderRadius: 2 }}
                  >
                    Add Disease
                  </Button>
                </Box>
              ) : (
                diseaseList
                  .filter((d) =>
                    d.name.toLowerCase().includes(searchTerm.toLowerCase()),
                  )
                  .map((disease) => {
                    const items = disease.items || [];
                    const treatmentItems =
                      items.length > 0
                        ? items
                        : disease.surah_id
                          ? [
                              {
                                type: "surah",
                                itemId: disease.surah_id,
                                count: disease.recitation_count || 7,
                                ayat_from: disease.ayat_from || 1,
                                ayat_to: disease.ayat_to || 7,
                              },
                            ]
                          : [];
                    const itemDetails = treatmentItems.map((item) => {
                      const type = String(item.type || "item").toLowerCase();
                      let name = "";

                      if (type === "surah") {
                        const surah = SURAHS.find(
                          (entry) =>
                            String(entry.surah_id) === String(item.itemId),
                        );
                        name = surah?.EnglishName || `Surah ${item.itemId}`;
                      } else {
                        const table =
                          type === "hadith"
                            ? "hadiths"
                            : type === "durood" || type === "darood"
                              ? "duroods"
                              : null;
                        if (table && db) {
                          try {
                            const result = db.exec(
                              `SELECT Name FROM ${table} WHERE Id = ?`,
                              [item.itemId],
                            );
                            name = result[0]?.values[0]?.[0] || "";
                          } catch (error) {
                            console.warn(`Could not load ${type} name:`, error);
                          }
                        }
                        name ||= `${type} ${item.itemId}`;
                      }

                      return {
                        ...item,
                        type,
                        name,
                        target: Number(item.count) || 7,
                      };
                    });
                    const totalRecitations = itemDetails.reduce(
                      (total, item) => total + item.target,
                      0,
                    );
                    let reference = "";
                    if (items.length > 1) {
                      reference = `${items.length} items (Surahs/Hadiths/Duroods)`;
                    } else if (items.length === 1 || disease.surah_id) {
                      const surahId =
                        items.length === 1 ? items[0].itemId : disease.surah_id;
                      const surah = SURAHS.find(
                        (s) => String(s.surah_id) === String(surahId),
                      );
                      const surahName = surah
                        ? surah.EnglishName
                        : `Surah ${surahId}`;
                      if (items.length === 1 && items[0].type !== "surah") {
                        reference = `${items[0].type} ${items[0].itemId}`;
                      } else {
                        const aFrom =
                          items.length === 1
                            ? items[0].ayat_from
                            : disease.ayat_from;
                        const aTo =
                          items.length === 1
                            ? items[0].ayat_to
                            : disease.ayat_to;
                        reference = `${surahName}, Ayat: ${aFrom || 1}-${aTo || 7}`;
                      }
                    } else {
                      reference = "Treatment Details inside";
                    }

                    return (
                      <Card
                        key={disease.disease_id}
                        sx={{
                          borderRadius: 3,
                          boxShadow: "0 4px 15px rgba(0,0,0,0.05)",
                          border: "1px solid #e0e0e0",
                          overflow: "hidden",
                          cursor: "pointer",
                          transition: "all 0.3s ease",
                          "&:hover": {
                            transform: "translateY(-4px)",
                            boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
                          },
                        }}
                      >
                        <CardContent sx={{ p: 3 }}>
                          <Box
                            sx={{
                              display: "flex",
                              justifyContent: "space-between",
                              alignItems: "center",
                              mb: 2,
                            }}
                          >
                            <Typography
                              variant="h5"
                              color="primary"
                              sx={{ fontWeight: "bold" }}
                            >
                              {disease.name}
                            </Typography>
                            <Chip
                              label="Recommended"
                              size="small"
                              sx={{
                                bgcolor: "primary.main",
                                color: "white",
                                fontWeight: "bold",
                                px: 1,
                              }}
                            />
                          </Box>

                          <Typography
                            variant="subtitle1"
                            sx={{
                              mb: 1,
                              fontWeight: 500,
                              color: "text.secondary",
                            }}
                          >
                            {itemDetails.length > 0
                              ? "Treatment Items"
                              : reference}
                          </Typography>

                          {itemDetails.length > 0 && (
                            <Box sx={{ display: "grid", gap: 1, mb: 2 }}>
                              {itemDetails.map((item, index) => (
                                <Box
                                  key={`${item.type}-${item.itemId}-${index}`}
                                  sx={{
                                    display: "flex",
                                    justifyContent: "space-between",
                                    alignItems: "center",
                                    gap: 2,
                                    p: 1.5,
                                    border: "1px solid",
                                    borderColor: "divider",
                                    borderRadius: 1,
                                  }}
                                >
                                  <Box sx={{ minWidth: 0 }}>
                                    <Typography
                                      variant="body1"
                                      sx={{ fontWeight: 600 }}
                                    >
                                      {item.name}
                                    </Typography>
                                    <Typography
                                      variant="caption"
                                      color="text.secondary"
                                    >
                                      {item.type === "surah"
                                        ? `Surah · Ayat ${item.ayat_from || 1}-${item.ayat_to || 7}`
                                        : item.type === "darood" ||
                                            item.type === "durood"
                                          ? "Darood"
                                          : "Hadith"}
                                    </Typography>
                                  </Box>
                                  <Typography
                                    variant="body2"
                                    sx={{
                                      flexShrink: 0,
                                      fontWeight: 600,
                                      color: "primary.main",
                                    }}
                                  >
                                    {item.target} recitations
                                  </Typography>
                                </Box>
                              ))}
                            </Box>
                          )}

                          <Divider sx={{ mb: 2 }} />

                          {disease.description && (
                            <Typography
                              variant="body1"
                              sx={{
                                mb: 3,
                                color: "text.secondary",
                                lineHeight: 1.6,
                              }}
                            >
                              {disease.description}
                            </Typography>
                          )}

                          <Box
                            sx={{
                              mb: 3,
                              display: "flex",
                              alignItems: "center",
                              gap: 1,
                            }}
                          >
                            <Typography
                              variant="h6"
                              sx={{ color: "text.primary", fontWeight: 500 }}
                            >
                              Total Recitation:{" "}
                              <span
                                style={{ fontWeight: "bold", color: "#0d472c" }}
                              >
                                {totalRecitations ||
                                  disease.recitation_count ||
                                  0}
                              </span>
                            </Typography>
                          </Box>

                          <Button
                            variant="contained"
                            size="large"
                            startIcon={<PlayArrowIcon />}
                            sx={{
                              borderRadius: 2,
                              px: 4,
                              textTransform: "none",
                              fontWeight: "bold",
                            }}
                            onClick={() =>
                              handleStartTreatment(disease, reference)
                            }
                          >
                            Start Treatment
                          </Button>
                        </CardContent>
                      </Card>
                    );
                  })
              )}
            </Box>
          )}
        </>
      )}

      <AddDiseaseDrawer
        open={openDrawer}
        onClose={() => {
          setOpenDrawer(false);
          if (selectedCategory) {
            fetchDiseasesByCategory(selectedCategory.value);
          }
        }}
      />
    </Box>
  );
};

export default Diseases;
